{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']

    segs = [(s['name'], s['importance'], s['minimum'], s['capacity']) for s in segments]
    names = [s[0] for s in segs]
    importances = [s[1] for s in segs]
    minimums = [s[2] for s in segs]
    capacities = [s[3] for s in segs]

    sum_min = sum(minimums)
    sum_cap = sum(capacities)
    if budget < sum_min or budget > sum_cap:
        raise ValueError('Budget out of feasible range')

    alloc = minimums[:]
    remaining = budget - sum_min

    while remaining > 0:
        best_i = None
        best_score = -1.0
        for i in range(len(segs)):
            if alloc[i] < capacities[i]:
                score = importances[i] / (alloc[i] + 1)
                if score > best_score:
                    best_score = score
                    best_i = i
        if best_i is None:
            break  # should not happen if budget <= sum_cap
        alloc[best_i] += 1
        remaining -= 1

    total = sum(alloc)
    by_name = {name: alloc[i] for i, name in enumerate(names)}
    return {
        'allocations': alloc,
        'by_name': by_name,
        'total': total
    }"
}
